import { type FC, memo, useId } from 'react'
import { tv } from 'tailwind-variants'

import type { ExtendElementPropsWithoutRef } from '../../types'

type Props = ExtendElementPropsWithoutRef<
  'svg',
  {
    /** コンポーネントのタイトル */
    alt?: string
    /** コンポーネントの幅 */
    width?: number | string
    /** コンポーネントの高さ */
    height?: number | string
    /** シンボルマークと「AI」のみで表示するかどうか */
    compact?: boolean
    /** ロゴの色。未指定の場合はカラーで表示する */
    fill?: 'black' | 'white' | 'brand'
  },
  { omit: 'role' | 'viewBox' | 'xmlns' | 'style' | 'aria-label' }
>

type BodyProps = {
  idPrefix: string
  monochrome: boolean
}

const classNameGenerator = tv({
  base: 'smarthr-ui-SmartHRAILogo forced-colors:shr-fill-[CanvasText]',
  variants: {
    compact: {
      false: 'shr-align-bottom',
    },
    fill: {
      black: 'shr-fill-black',
      white: 'shr-fill-white',
      brand: 'shr-fill-brand',
    } satisfies Record<NonNullable<Props['fill']>, string>,
  },
})

export const SmartHRAILogo = memo<Props>(
  ({ alt, width, height, compact = true, fill, className, ...rest }) => {
    const id = useId()
    const { name, viewBox, Body } = compact ? COMPACT_LOGO : LOGOTYPE
    // HINT: useIdは別のReact rootと重複しうるため、nameを含めて異なる形状のグラデーションを参照しないようにする
    const idPrefix = `${id}-${name}`
    const monochrome = !!fill

    return (
      <svg
        {...rest}
        role="img"
        viewBox={viewBox}
        // HINT: 単色の場合はclassNameのfillを継承させる
        fill={monochrome ? undefined : 'none'}
        xmlns="http://www.w3.org/2000/svg"
        // eslint-disable-next-line smarthr/best-practice-for-tailwind-variants -- 再レンダリングされる可能性はほぼないため
        className={classNameGenerator({ className, compact, fill })}
        style={width ? { width: convertValue(width) } : { height: convertValue(height || '1.5em') }}
        aria-label={alt || 'SmartHR（スマートHR） AI'}
      >
        <Body idPrefix={idPrefix} monochrome={monochrome} />
      </svg>
    )
  },
)

